1061	// Base class for nodes which communicate over channels.
1062	class ChannelNode : public Node {
1063	 public:
1064	  static constexpr std::array<Op, 2> kOps = {Op::kReceive, Op::kSend};
1065	
1066	  ChannelNode(const SourceInfo& loc, Op op, Type* type,
1067	              std::string_view channel_name, ChannelDirection direction,
1068	              bool has_predicate, std::string_view name, FunctionBase* function)
1069	      : Node(op, type, loc, name, function),
1070	        channel_name_(channel_name),
1071	        direction_(direction),
1072	        has_predicate_(has_predicate) {}
1073	
1074	  const std::string& channel_name() const { return channel_name_; }
1075	
1076	  // Return either the channel (old-style proc) or the channel reference
1077	  // (new-style proc) for this channel op node.
1078	  absl::StatusOr<ChannelRef> GetChannelRef() const;
1079	
1080	  // Return the channel interface for this channel op node.
1081	  // Returns an error if the function is not a new-style proc.
1082	  absl::StatusOr<ChannelInterface*> GetChannelInterface() const;
1083	
1084	  // Returns the direction this node communicates on the channel.
1085	  ChannelDirection direction() const { return direction_; }
1086	
1087	  // Returns the type of the data payload communicated on the channel.
1088	  Type* GetPayloadType() const;
1089	
1090	  // Replaces the channel with the channel with the given name. Returns an
1091	  // error if no such channel/channel-ref exists.
1092	  absl::Status ReplaceChannel(std::string_view new_channel_name);
1093	
1094	  Node* token() const { return operand(0); }
1095	
1096	  // Replaces the token operand with the given node. Returns an error if
1097	  // `new_token` is not token-typed.
1098	  absl::Status ReplaceToken(Node* new_token) {
1099	    XLS_RET_CHECK(new_token->GetType()->IsToken()) << absl::StreamFormat(
1100	        "Expected new token value to be token typed, is: %s",
1101	        new_token->GetType()->ToString());
1102	    XLS_RETURN_IF_ERROR(ReplaceOperandNumber(0, new_token));
1103	    return absl::OkStatus();
1104	  }
1105	
1106	  std::optional<Node*> predicate() const {
1107	    // The predicate is the last operand.
1108	    return has_predicate_ ? std::optional<Node*>(operands().back())
1109	                          : std::nullopt;
1110	  }
1111	
1112	  absl::Status SetPredicate(std::optional<Node*> predicate) {
1113	    if (predicate) {
1114	      Node* new_predicate = *predicate;
1115	      XLS_RET_CHECK(new_predicate->GetType()->IsBits() &&
1116	                    new_predicate->BitCountOrDie() == 1)
1117	          << absl::StreamFormat(
1118	                 "Expected predicate to be single-bit bits type, is: %s",
1119	                 new_predicate->GetType()->ToString());
1120	      if (has_predicate_) {
1121	        return ReplaceOperandNumber(operand_count() - 1, new_predicate);
1122	      }
1123	      has_predicate_ = true;
1124	      AddOperand(new_predicate);
1125	      return absl::OkStatus();
1126	    }
1127	    if (!has_predicate_) {
1128	      // Already don't have a predicate?
1129	      return absl::OkStatus();
1130	    }
1131	    has_predicate_ = false;
1132	    return RemoveOptionalOperand(operand_count() - 1);
1133	  }
1134	
1135	  absl::Status ReplacePredicate(Node* new_predicate) {
1136	    XLS_RET_CHECK(has_predicate_) << absl::StreamFormat(
1137	        "Cannot replace predicate of node `%s` as it does not currently have a "
1138	        "predicate",
1139	        GetName());
1140	    XLS_RET_CHECK(new_predicate->GetType()->IsBits() &&
1141	                  new_predicate->BitCountOrDie() == 1)
1142	        << absl::StreamFormat(
1143	               "Expected predicate to be single-bit bits type, is: %s",
1144	               new_predicate->GetType()->ToString());
1145	    XLS_RETURN_IF_ERROR(
1146	        ReplaceOperandNumber(operand_count() - 1, new_predicate));
1147	    return absl::OkStatus();
1148	  }
1149	
1150	 private:
1151	  std::string channel_name_;
1152	  ChannelDirection direction_;
1153	  bool has_predicate_;
1154	};
