1247	               ? ReplaceOperandNumber(*load_enable_operand_number(),
1248	                                      new_operand)
1249	               : absl::InternalError(
1250	                     "Unable to replace load enable on RegisterWrite -- "
1251	                     "register does not have an existing load enable operand.");
1252	  }
