1254	  absl::Status SetReset(std::optional<Node*> reset) {
1255	    // Clear existing reset.
1256	    if (has_reset_) {
1257	      XLS_RETURN_IF_ERROR(RemoveOptionalOperand(*reset_operand_number()));
1258	      has_reset_ = false;
1259	    }
1260	    if (!reset.has_value()) {
1261	      return absl::OkStatus();
1262	    }
1263	    has_reset_ = true;
1264	    AddOperand(reset.value());
1265	    return absl::OkStatus();
1266	  }
1267	
1268	  absl::StatusOr<int64_t> load_enable_operand_number() const {
1269	    if (!has_load_enable_) {
1270	      return absl::InternalError("load_enable is not present");
1271	    }
1272	    return 1;
1273	  }
1274	
1275	  absl::StatusOr<int64_t> reset_operand_number() const {
1276	    if (!has_reset_) {
1277	      return absl::InternalError("reset is not present");
1278	    }
1279	    return has_load_enable_ ? 2 : 1;
1280	  }
1281	
1282	  bool IsDefinitelyEqualTo(const Node* other) const final;
1283	
1284	 private:
1285	  Register* reg_;
1286	  bool has_load_enable_;
1287	  bool has_reset_;
1288	};
